using namespace ui;

menu_letter2 SkillMenuEntry::m_letter;
SkillMenu skm;

static string _format_skill_target(int target);

// The generic menu wrapper uses locale wcwidth(), which can report zero for
// CJK text in the C locale. Count wide Unicode glyphs as two cells and keep
// markup tags intact so the help panel fits the actual terminal grid.
static int _skill_cells(char32_t c)
{
    // Common non-spacing mark blocks. These ranges are locale independent;
    // in particular, symbols such as → (U+2192) and … (U+2026) stay one cell.
    if ((c >= 0x0300 && c <= 0x036f)
        || (c >= 0x1ab0 && c <= 0x1aff)
        || (c >= 0x1dc0 && c <= 0x1dff)
        || (c >= 0x20d0 && c <= 0x20ff)
        || (c >= 0xfe00 && c <= 0xfe0f)
        || (c >= 0xfe20 && c <= 0xfe2f)
        || (c >= 0xe0100 && c <= 0xe01ef))
        return 0;
    if ((c >= 0x1100 && c <= 0x115f) || c == 0x2329 || c == 0x232a
        || (c >= 0x2e80 && c <= 0xa4cf && c != 0x303f)
        || (c >= 0xac00 && c <= 0xd7a3)
        || (c >= 0xf900 && c <= 0xfaff)
        || (c >= 0xfe10 && c <= 0xfe19)
        || (c >= 0xfe30 && c <= 0xfe6f)
        || (c >= 0xff00 && c <= 0xff60)
        || (c >= 0xffe0 && c <= 0xffe6)
        || (c >= 0x20000 && c <= 0x2fffd)
        || (c >= 0x30000 && c <= 0x3fffd))
        return 2;
    return 1;
}

static string _skill_wrap(const string &text, int width)
{
    string out;
    int col = 0;
    for (size_t i = 0; i < text.size();)
    {
        // The formatted-string grammar uses << for a literal less-than sign.
        // Consume it before looking for a color tag's closing '>'.
        if (text.compare(i, 2, "<<") == 0)
        {
            out += "<<";
            ++col;
            i += 2;
            continue;
        }
        if (text[i] == '<')
        {
            const size_t end = text.find('>', i);
            if (end != string::npos)
            {
                out.append(text, i, end - i + 1);
                i = end + 1;
                continue;
            }
        }
        if (text[i] == '\n')
        {
            out += '\n';
            col = 0;
            ++i;
            continue;
        }
        char32_t c = 0;
        const int bytes = utf8towc(&c, text.c_str() + i);
        const size_t n = bytes > 0 ? size_t(bytes) : 1;
        const int cells = bytes > 0 ? _skill_cells(c) : 1;
        if (col && col + cells > width)
        {
            out += '\n';
            col = 0;
        }
        out.append(text, i, n);
        col += cells;
        i += n;
    }
    return out;
}

static int _skill_line_count(const string &text)
{
    return 1 + std::count(text.begin(), text.end(), '\n');
}

static int _skill_help_rows(int current_rows, int text_rows, int max_rows)
{
    return min(max(current_rows, text_rows), max(1, max_rows));
}

static int _skill_help_columns(int left, int right, int unit)
{
    // Use the text item's actual bounds, not the enclosing menu's origin.
    // Leave one display cell between the last glyph and the frame.
    return max(1, (right - left) / max(1, unit) - 1);
}

static int _skill_help_rows_available(int screen_bottom, int current_rows,
                                      int footer_bottom, int unit)
{
    unit = max(1, unit);
    // Footer items move by the same delta as the help box. Reserve their full
    // vertical span, including switch rows wrapped by add_item(), rather than
    // just the height of the tallest individual button.
    return max(1, (screen_bottom - footer_bottom + current_rows * unit) / unit);
}

static int _skill_text_width(const string &text)
{
    int width = 0;
    for (size_t i = 0; i < text.size();)
    {
        if (text.compare(i, 2, "<<") == 0)
        {
            width += _skill_cells('<');
            i += 2;
            continue;
        }
        if (text[i] == '<')
        {
            const size_t end = text.find('>', i);
            if (end != string::npos)
            {
                i = end + 1;
                continue;
            }
        }
        char32_t c = 0;
        const int bytes = utf8towc(&c, text.c_str() + i);
        if (bytes <= 0)
        {
            ++i;
            ++width;
        }
        else
        {
            i += size_t(bytes);
            width += _skill_cells(c);
        }
    }
    return width;
}

static ZhArg _skill_cause_arg(const vector<string> &causes)
{
    const string canonical = comma_separated_line(causes.begin(), causes.end());
    string localized;
    bool supported = true;
    for (const string &cause : causes)
    {
        const ZhArg word = zh_word_arg("cause", "skill.cause.", cause);
        if (!localized.empty())
            localized += "、";
        localized += word.localized;
        supported = supported && word.supported;
    }
    return {"cause", ZhArgType::Text, canonical, localized, supported};
}

#ifdef USE_TILE_LOCAL
bool SkillTextTileItem::handle_mouse(const wm_mouse_event& me)
{
    if (me.event == wm_mouse_event::PRESS
        && (me.button == wm_mouse_event::LEFT && me.mod & TILES_MOD_SHIFT))
    {
        skill_type sk = skill_type(get_id());
        if (is_invalid_skill(sk))
            return false;

        skm.select(sk, 'A');
        return true;
    }
    else if (me.event == wm_mouse_event::PRESS
        && me.button == wm_mouse_event::RIGHT)
    {
        skill_type sk = skill_type(get_id());
        if (is_invalid_skill(sk))
            return false;
        describe_skill(sk);
        return true;
    }
    else
        return false;
}
#endif

#define NAME_SIZE 20
#define LEVEL_SIZE 5
#define PROGRESS_SIZE 6
#define APTITUDE_SIZE 5
SkillMenuEntry::SkillMenuEntry(coord_def coord)
{
#ifdef USE_TILE_LOCAL
    m_name = new SkillTextTileItem();
#else
    m_name = new TextItem();
#endif

    m_level = new NoSelectTextItem();
    m_progress = new EditableTextItem();
    m_progress->set_editable(false);
    m_aptitude = new FormattedTextItem();
    m_aptitude->allow_highlight(false);

#ifdef USE_TILE_LOCAL
    const int height = skm.get_line_height();
    m_name->set_height(height);
    if (is_set(SKMF_SKILL_ICONS))
    {
        m_level->set_height(height);
        m_progress->set_height(height);
        m_aptitude->set_height(height);
    }
#endif

    skm.add_item(m_name, NAME_SIZE + (is_set(SKMF_SKILL_ICONS) ? 4 : 0), coord);
    m_name->set_highlight_colour(RED);
    skm.add_item(m_level, LEVEL_SIZE, coord);
    skm.add_item(m_progress, PROGRESS_SIZE, coord);
    skm.add_item(m_aptitude, APTITUDE_SIZE, coord);
}

// Public methods
int SkillMenuEntry::get_id()
{
    return m_name->get_id();
}

TextItem* SkillMenuEntry::get_name_item() const
{
    return m_name;
}

skill_type SkillMenuEntry::get_skill() const
{
    return m_sk;
}

static bool _show_skill(skill_type sk, skill_menu_state state)
{
    switch (state)
    {
    case SKM_SHOW_DEFAULT:
        return you.can_currently_train[sk] && (you.should_show_skill[sk]
                                               || you.training[sk])
            || you.skill(sk, 10, false, false);
    case SKM_SHOW_ALL:     return true;
    default:               return false;
    }
}

bool SkillMenuEntry::is_selectable(bool)
{
    if (is_invalid_skill(m_sk))
        return false;

    if (is_set(SKMF_HELP))
        return true;

    if (you.has_mutation(MUT_DISTRIBUTED_TRAINING))
        return false;

    if (mastered())
        return false;

    // if it's visible at this point, it's selectable.
    return true;
}

bool SkillMenuEntry::is_set(int flag) const
{
    return skm.is_set(flag);
}

bool SkillMenuEntry::mastered() const
{
    return (is_set(SKMF_EXPERIENCE) ? skm.get_raw_skill_level(m_sk)
                                    : you.skills[m_sk]) >= MAX_SKILL_LEVEL;
}

void SkillMenuEntry::refresh(bool keep_hotkey)
{
    if (m_sk == SK_TITLE)
        set_title();
    else if (is_invalid_skill(m_sk) || is_useless_skill(m_sk))
        _clear();
    else
    {
        set_name(keep_hotkey);
        set_display();
        if (is_set(SKMF_APTITUDE))
            set_aptitude();
    }
}

void SkillMenuEntry::set_display()
{
    if (m_sk == SK_TITLE)
        set_title();

    if (is_invalid_skill(m_sk))
        return;

    switch (skm.get_state(SKM_VIEW))
    {
    case SKM_VIEW_TRAINING:  set_training();         break;
    case SKM_VIEW_COST:      set_cost();             break;
    case SKM_VIEW_TARGETS:   set_targets();          break;
    case SKM_VIEW_PROGRESS:  set_progress();         break;
    case SKM_VIEW_NEW_LEVEL: set_new_level();        break;
    case SKM_VIEW_POINTS:    set_points();           break;
    default: die("Invalid view state.");
    }
}

void SkillMenuEntry::set_name(bool keep_hotkey)
{
    if (is_invalid_skill(m_sk))
        return;

    if (!keep_hotkey)
        m_name->clear_hotkeys();

    if (is_selectable(keep_hotkey))
    {
        if (!keep_hotkey)
        {
            m_name->add_hotkey(++m_letter);
            m_name->add_hotkey(toupper_safe(m_letter));
        }
        m_name->set_id(m_sk);
        m_name->allow_highlight(true);
    }
    else
    {
        m_name->set_id(-1);
        m_name->allow_highlight(false);
    }

    const string skill = skill_name(m_sk);
    ZhArg skill_arg = zh_glossary_name("skill", "skill.name", skill);
    string row = zh_message("skill.menu.entry_name", {
        zh_key("prefix", get_prefix()), skill_arg}).display();
    m_name->set_text_pretranslated(row);
    m_name->set_fg_colour(get_colour());
#ifdef USE_TILE_LOCAL
    if (is_set(SKMF_SKILL_ICONS))
    {
        m_name->clear_tile();
        if (you.skills[m_sk] >= MAX_SKILL_LEVEL)
            m_name->add_tile(tile_def(tileidx_skill(m_sk, TRAINING_MASTERED)));
        else if (you.training[m_sk] == TRAINING_DISABLED)
            m_name->add_tile(tile_def(tileidx_skill(m_sk, TRAINING_INACTIVE)));
        else
            m_name->add_tile(tile_def(tileidx_skill(m_sk, you.train[m_sk])));
    }
#endif
    set_level();
}

void SkillMenuEntry::set_skill(skill_type sk)
{
    m_sk = sk;
    refresh(false);
}

// Private Methods
void SkillMenuEntry::_clear()
{
    m_sk = SK_NONE;

    m_name->set_text_pretranslated("");
    m_level->set_text_pretranslated("");
    m_progress->set_text_pretranslated("");
    m_aptitude->set_text_pretranslated("");

    m_name->set_id(-1);
    m_name->clear_hotkeys();
    m_name->allow_highlight(false);
#ifdef USE_TILE_LOCAL
    if (is_set(SKMF_SKILL_ICONS))
        m_name->clear_tile();
#endif
}
COLOURS SkillMenuEntry::get_colour() const
{
    // Skills being actively trained may get further distinction.
    bool use_bright_colour = you.train[m_sk] == TRAINING_ENABLED
        || you.train[m_sk] == TRAINING_FOCUSED;

    if (is_set(SKMF_HELP))
        return LIGHTGRAY;
    else if (skm.get_state(SKM_LEVEL) == SKM_LEVEL_ENHANCED
             && you.skill(m_sk, 10, true) != you.skill(m_sk, 10, false))
    {
        if (you.skill(m_sk, 10, true) < you.skill(m_sk, 10, false))
            return use_bright_colour ? LIGHTGREEN : GREEN;
        else
            return use_bright_colour ? LIGHTMAGENTA : MAGENTA;
    }
    else if (mastered())
        return YELLOW;
    else if (!you.training[m_sk])
        return DARKGREY;
    else if (you.skill_manual_points[m_sk])
        return LIGHTBLUE;
    else if (you.train[m_sk] == TRAINING_FOCUSED)
        return WHITE;
    else
        return LIGHTGREY;
}

string SkillMenuEntry::get_prefix()
{
    int letter;
    const vector<int> hotkeys = m_name->get_hotkeys();

    if (!hotkeys.empty())
        letter = hotkeys[0];
    else
        letter = ' ';

    const int sign = (!you.can_currently_train[m_sk] || mastered()) ? ' ' :
                                   (you.train[m_sk] == TRAINING_FOCUSED) ? '*' :
                                          you.train[m_sk] ? '+'
                                                          : '-';
    return make_stringf(" %c %c", letter, sign);
}

void SkillMenuEntry::set_aptitude()
{
    string text = "<white>";

    const bool manual = you.skill_manual_points[m_sk] > 0;
    const int apt = species_apt(m_sk, you.species);

    if (apt != 0)
        text += make_stringf("%+d", apt);
    else
        text += make_stringf(" %d", apt);

    text += "</white>";
    if (apt < 10 && apt > -10)
        text += " ";

    if (manual)
    {
        skm.set_flag(SKMF_MANUAL);
        text += "<lightred>+4</lightred>";
    }

    m_aptitude->set_text_pretranslated(text);
}

void SkillMenuEntry::set_level()
{
    int level;
    const bool real = skm.get_state(SKM_LEVEL) != SKM_LEVEL_ENHANCED;

    if (is_set(SKMF_EXPERIENCE))
        level = skm.get_saved_skill_level(m_sk, real);
    else
        level = you.skill(m_sk, 10, real);

    if (mastered())
        m_level->set_text_pretranslated(to_string(level / 10));
    else
        m_level->set_text_pretranslated(make_stringf("%4.1f", level / 10.0));
    m_level->set_fg_colour(get_colour());
}

void SkillMenuEntry::set_new_level()
{
    m_progress->set_editable(false);

    const bool real = skm.get_state(SKM_LEVEL) != SKM_LEVEL_ENHANCED;
    int new_level = 0;
    if (is_set(SKMF_EXPERIENCE) && is_selectable())
    {
        new_level = you.skill(m_sk, 10, real);
        m_progress->set_fg_colour(CYAN);
        if (you.training[m_sk])
            m_progress->set_text_pretranslated(make_stringf("> %4.1f", new_level / 10.0));
        else
            m_progress->set_text_pretranslated(string(PROGRESS_SIZE, ' '));
        return;
    }

    if (is_selectable())
        m_progress->set_text_pretranslated(make_stringf("> %4.1f", new_level / 10.0));
    else
        m_progress->set_text_pretranslated("");

}

void SkillMenuEntry::set_points()
{
    m_progress->set_text_pretranslated(make_stringf("%5d", you.skill_points[m_sk]));
    m_progress->set_fg_colour(LIGHTGREY);
    m_progress->set_editable(false);
}

void SkillMenuEntry::set_progress()
{
    if (mastered())
        m_progress->set_text_pretranslated("");
    else
    {
        m_progress->set_text_pretranslated(make_stringf(" %2d%%",
                                          get_skill_percentage(m_sk)));
    }
    m_progress->set_fg_colour(CYAN);
    m_progress->set_editable(false);
}

EditableTextItem *SkillMenuEntry::get_progress()
{
    return m_progress;
}

void SkillMenuEntry::set_targets()
{
    int target = you.get_training_target(m_sk);
    if (target == 0)
    {
        m_progress->set_text_pretranslated("--");
        m_progress->set_fg_colour(DARKGREY);
    }
    else
    {
        m_progress->set_text_pretranslated(_format_skill_target(target));
        if (target_met(m_sk))
            m_progress->set_fg_colour(DARKGREY); // mainly comes up in wizmode
        else
            m_progress->set_fg_colour(get_colour());
    }
    m_progress->set_editable(true, 4);
}

void SkillMenuEntry::set_title()
{
    m_name->allow_highlight(false);
    m_name->set_text_pretranslated(zh_message("skill.menu.title.skill").display());
    m_level->set_text_pretranslated(zh_message("skill.menu.title.level").display());

    m_name->set_fg_colour(BLUE);
    m_level->set_fg_colour(BLUE);
    m_progress->set_fg_colour(BLUE);

    if (is_set(SKMF_APTITUDE))
        m_aptitude->set_text_pretranslated("<blue>适性</blue>");

    switch (skm.get_state(SKM_VIEW))
    {
    case SKM_VIEW_TRAINING:  m_progress->set_text_pretranslated(zh_message("skill.menu.title.train").display()); break;
    case SKM_VIEW_TARGETS:   m_progress->set_text_pretranslated(zh_message("skill.menu.title.target").display()); break;
    case SKM_VIEW_PROGRESS:  m_progress->set_text_pretranslated(zh_message("skill.menu.title.progress").display()); break;
    case SKM_VIEW_POINTS:    m_progress->set_text_pretranslated(zh_message("skill.menu.title.points").display());break;
    case SKM_VIEW_COST:      m_progress->set_text_pretranslated(zh_message("skill.menu.title.cost").display());  break;
    case SKM_VIEW_NEW_LEVEL: m_progress->set_text_pretranslated(zh_message("skill.menu.title.new_level").display()); break;
    default: die("Invalid view state.");
    }
}

void SkillMenuEntry::set_training()
{
    m_progress->set_editable(false);

    if (!you.training[m_sk])
        m_progress->set_text_pretranslated("");
    else
        m_progress->set_text_pretranslated(make_stringf("%2d%%", you.training[m_sk]));
    m_progress->set_fg_colour(BROWN);
}

void SkillMenuEntry::set_cost()
{
    m_progress->set_editable(false);

    if (you.skills[m_sk] == MAX_SKILL_LEVEL)
        return;
    if (you.skill_manual_points[m_sk])
        m_progress->set_fg_colour(LIGHTRED);
    else
        m_progress->set_fg_colour(CYAN);

    auto ratio = scaled_skill_cost(m_sk);
    // Don't let the displayed number go greater than 4 characters
    if (ratio > 0)
        m_progress->set_text_pretranslated(make_stringf("%4.*f", ratio < 100 ? 1 : 0, ratio));
}

